package campusloop;
import com.sun.net.httpserver.*;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.sql.*;import java.time.*;import java.util.*;import java.util.concurrent.*;import static campusloop.Database.*;import static campusloop.Json.obj;
/** Java 17 HTTP server. All write operations are serialized and committed atomically. */
public final class App {
 private final Database db;private final Map<String,Session> sessions=new ConcurrentHashMap<>();private final Map<String,Attempts> attempts=new ConcurrentHashMap<>();private final Object writes=new Object();private final boolean secure=Boolean.parseBoolean(System.getenv().getOrDefault("COOKIE_SECURE","false"));
 private record Session(long userId,String csrf,Instant expires){}private static class Attempts{int count;Instant until=Instant.now().plusSeconds(600);}
 private static final class Fault extends RuntimeException{final int code;Fault(int c,String s){super(s);code=c;}}
 public App(Path dir)throws Exception{db=new Database(dir);bootstrap();}
 private void bootstrap()throws Exception{try(var c=db.connect()){if(!query(c,"SELECT id FROM users WHERE role='ADMIN'").isEmpty())return;String email=System.getenv("ADMIN_EMAIL"),pass=System.getenv("ADMIN_PASSWORD");if(email==null||pass==null){Console console=System.console();if(console==null)throw new IllegalStateException("First run: set ADMIN_EMAIL and ADMIN_PASSWORD (minimum 10 characters), or start interactively using run.bat/run.sh.");email=console.readLine("Create administrator — email: ");char[] chars=console.readPassword("Administrator password (minimum 10 characters): ");pass=new String(chars);Arrays.fill(chars,'\0');}email=email.trim().toLowerCase(Locale.ROOT);email(email);password(pass);update(c,"INSERT INTO users(name,email,department,password_hash,role) VALUES(?,?,?,?,?)","College Administrator",email,"Administration",Security.password(pass),"ADMIN");System.out.println("Administrator created. Keep these credentials private.");}}
 public static void main(String[] args)throws Exception{int port=Integer.parseInt(System.getenv().getOrDefault("PORT","8080"));var app=new App(Path.of(System.getenv().getOrDefault("DATA_DIR","data")));var server=HttpServer.create(new InetSocketAddress(System.getenv().getOrDefault("BIND_ADDRESS","127.0.0.1"),port),64);server.createContext("/",app::handle);server.setExecutor(new ThreadPoolExecutor(4,16,30,TimeUnit.SECONDS,new ArrayBlockingQueue<>(100),new ThreadPoolExecutor.CallerRunsPolicy()));server.start();Runtime.getRuntime().addShutdownHook(new Thread(()->server.stop(1)));System.out.println("CampusLoop ready at http://localhost:"+port+" (Ctrl+C to stop)");}
 private void handle(HttpExchange x)throws IOException{try{x.getResponseHeaders().set("X-Content-Type-Options","nosniff");x.getResponseHeaders().set("Referrer-Policy","same-origin");x.getResponseHeaders().set("Content-Security-Policy","default-src 'self'; script-src 'self'; style-src 'self'; img-src 'self' data:; connect-src 'self'; frame-ancestors 'none'; base-uri 'self'; form-action 'self'");x.getResponseHeaders().set("Cache-Control","no-store");String path=x.getRequestURI().getPath();if(!path.startsWith("/api/")){asset(x,path);return;}if(!Set.of("GET","POST").contains(x.getRequestMethod()))throw new Fault(405,"Method not allowed");if(path.equals("/api/health")&&x.getRequestMethod().equals("GET")){send(x,200,obj("ok",true));return;}Session session=session(x);Map<String,Object> user=null;try(var c=db.connect()){if(session!=null){var rows=query(c,"SELECT id,name,email,student_id,department,role FROM users WHERE id=?",session.userId);if(!rows.isEmpty())user=rows.get(0);}}
 Map<String,String> f=new HashMap<>();boolean post=x.getRequestMethod().equals("POST");if(post){String origin=x.getRequestHeaders().getFirst("Origin");if(origin!=null){try{var u=URI.create(origin);if(!Objects.equals(u.getRawAuthority(),x.getRequestHeaders().getFirst("Host"))||!Set.of("http","https").contains(u.getScheme()))throw new Fault(403,"Invalid request origin");}catch(IllegalArgumentException ex){throw new Fault(403,"Invalid request origin");}}String ct=x.getRequestHeaders().getFirst("Content-Type");if(ct==null||!ct.startsWith("application/x-www-form-urlencoded"))throw new Fault(415,"Expected form request");byte[] bytes=x.getRequestBody().readNBytes(16385);if(bytes.length>16384)throw new Fault(413,"Request too large");f=parse(new String(bytes,StandardCharsets.UTF_8));if(!Set.of("/api/login","/api/signup").contains(path)){if(user==null)throw new Fault(401,"Please sign in");if(!Objects.equals(session.csrf,x.getRequestHeaders().getFirst("X-CSRF-Token")))throw new Fault(403,"Session security token is missing or expired");}}
 if(path.equals("/api/me")&&!post){send(x,200,obj("user",user,"csrf",session==null?null:session.csrf));return;}
 if(path.equals("/api/signup")&&post){rate(x);String name=text(f,"name",2,80),email=text(f,"email",3,160).toLowerCase(Locale.ROOT),sid=text(f,"studentId",2,40).toUpperCase(Locale.ROOT),department=text(f,"department",2,80),pass=f.getOrDefault("password","");email(email);password(pass);if(!sid.matches("[A-Z0-9_-]{2,40}"))throw new Fault(400,"Student ID may contain letters, numbers, hyphens, and underscores");synchronized(writes){try(var c=db.connect()){if(!query(c,"SELECT id FROM users WHERE email=? OR student_id=?",email,sid).isEmpty())throw new Fault(409,"Email or student ID already registered");update(c,"INSERT INTO users(name,email,student_id,department,password_hash,role) VALUES(?,?,?,?,?,?)",name,email,sid,department,Security.password(pass),"STUDENT");long id=((Number)query(c,"SELECT id FROM users WHERE email=?",email).get(0).get("id")).longValue();startSession(x,id);}}send(x,201,obj("ok",true));return;}
 if(path.equals("/api/login")&&post){rate(x);String email=f.getOrDefault("email","").trim().toLowerCase(Locale.ROOT),pass=f.getOrDefault("password","");if(pass.length()>128)throw new Fault(400,"Invalid credentials");try(var c=db.connect()){var rows=query(c,"SELECT id,password_hash FROM users WHERE email=?",email);String hash=rows.isEmpty()?DUMMY:rows.get(0).get("password_hash").toString();if(!Security.verify(pass,hash)||rows.isEmpty())throw new Fault(401,"Incorrect email or password");startSession(x,((Number)rows.get(0).get("id")).longValue());}send(x,200,obj("ok",true));return;}
 if(path.equals("/api/logout")&&post){sessions.remove(cookie(x));x.getResponseHeaders().add("Set-Cookie","CLSESSION=; Path=/; HttpOnly; SameSite=Strict; Max-Age=0"+(secure?"; Secure":""));send(x,200,obj("ok",true));return;}
 if(path.equals("/api/events")&&!post){try(var c=db.connect()){var es=query(c,"SELECT e.*, (SELECT COUNT(*) FROM registrations r WHERE r.event_id=e.id) booked FROM events e ORDER BY starts_at");send(x,200,obj("events",es,"serverTime",LocalDateTime.now().toString()));}return;}
 if(user==null)throw new Fault(401,"Please sign in");long uid=((Number)user.get("id")).longValue();boolean admin=user.get("role").equals("ADMIN");
 if(path.equals("/api/registrations")&&!post){try(var c=db.connect()){send(x,200,obj("registrations",query(c,"SELECT r.*,e.name,e.starts_at,e.venue,e.status FROM registrations r JOIN events e ON r.event_id=e.id WHERE r.user_id=? ORDER BY e.starts_at",uid)));}return;}
 if((path.equals("/api/register")||path.equals("/api/unregister"))&&post){if(admin)throw new Fault(403,"Use a student account to register");long id=id(f,"eventId");synchronized(writes){try(var c=db.connect()){c.setAutoCommit(false);try{var ev=event(c,id);if(!ev.get("status").equals("OPEN"))throw new Fault(409,"This event was cancelled");if(!LocalDateTime.parse(ev.get("starts_at").toString()).isAfter(LocalDateTime.now()))throw new Fault(409,"Registration changes close when the event starts");var existing=query(c,"SELECT id FROM registrations WHERE event_id=? AND user_id=?",id,uid);if(path.equals("/api/register")){if(!existing.isEmpty())throw new Fault(409,"You are already registered");int count=((Number)query(c,"SELECT COUNT(*) n FROM registrations WHERE event_id=?",id).get(0).get("n")).intValue();if(count>=((Number)ev.get("capacity")).intValue())throw new Fault(409,"This event is full");update(c,"INSERT INTO registrations(event_id,user_id,registered_at) VALUES(?,?,?)",id,uid,Instant.now().toString());}else{if(existing.isEmpty())throw new Fault(404,"Registration not found");update(c,"DELETE FROM registrations WHERE event_id=? AND user_id=?",id,uid);}c.commit();}catch(Exception ex){c.rollback();throw ex;}}}send(x,200,obj("ok",true));return;}
 if(!admin)throw new Fault(403,"Administrator access required");
 if(path.equals("/api/admin/participants")&&!post){var q=parse(x.getRequestURI().getRawQuery());long id=id(q,"eventId");try(var c=db.connect()){event(c,id);send(x,200,obj("participants",query(c,"SELECT r.id,r.registered_at,r.attended,u.name,u.email,u.student_id,u.department FROM registrations r JOIN users u ON r.user_id=u.id WHERE r.event_id=? ORDER BY u.name",id)));}return;}
 if(path.equals("/api/admin/save-event")&&post){String name=text(f,"name",3,100),cat=text(f,"category",3,20),desc=text(f,"description",10,2000),venue=text(f,"venue",3,100),date=text(f,"startsAt",10,30);int cap=(int)id(f,"capacity");if(cap>10000)throw new Fault(400,"Maximum capacity is 10,000");if(!Set.of("Technical","Cultural","Sports","Workshop","Community").contains(cat))throw new Fault(400,"Invalid category");LocalDateTime start;try{start=LocalDateTime.parse(date);}catch(Exception ex){throw new Fault(400,"Invalid date and time");}if(!start.isAfter(LocalDateTime.now()))throw new Fault(400,"Choose a future date and time");synchronized(writes){try(var c=db.connect()){if(f.containsKey("id")&&!f.get("id").isBlank()){long id=id(f,"id");var ev=event(c,id);if(!ev.get("status").equals("OPEN"))throw new Fault(409,"Cancelled events cannot be edited");int booked=((Number)query(c,"SELECT COUNT(*) n FROM registrations WHERE event_id=?",id).get(0).get("n")).intValue();if(cap<booked)throw new Fault(409,"Capacity cannot be below the number of registrations");update(c,"UPDATE events SET name=?,category=?,description=?,starts_at=?,venue=?,capacity=? WHERE id=?",name,cat,desc,start.toString(),venue,cap,id);}else update(c,"INSERT INTO events(name,category,description,starts_at,venue,capacity) VALUES(?,?,?,?,?,?)",name,cat,desc,start.toString(),venue,cap);}}send(x,200,obj("ok",true));return;}
 if(path.equals("/api/admin/cancel-event")&&post){long id=id(f,"eventId");synchronized(writes){try(var c=db.connect()){event(c,id);update(c,"UPDATE events SET status='CANCELLED' WHERE id=?",id);}}send(x,200,obj("ok",true));return;}
 if(path.equals("/api/admin/delete-event")&&post){long id=id(f,"eventId");synchronized(writes){try(var c=db.connect()){event(c,id);if(((Number)query(c,"SELECT COUNT(*) n FROM registrations WHERE event_id=?",id).get(0).get("n")).intValue()>0)throw new Fault(409,"Events with registrations must be cancelled, not deleted");update(c,"DELETE FROM events WHERE id=?",id);}}send(x,200,obj("ok",true));return;}
 if(path.equals("/api/admin/attendance")&&post){long id=id(f,"registrationId");boolean attended=f.getOrDefault("attended","false").equals("true");synchronized(writes){try(var c=db.connect()){var rs=query(c,"SELECT r.id,e.status FROM registrations r JOIN events e ON e.id=r.event_id WHERE r.id=?",id);if(rs.isEmpty())throw new Fault(404,"Registration not found");if(rs.get(0).get("status").equals("CANCELLED"))throw new Fault(409,"Cannot change attendance for a cancelled event");update(c,"UPDATE registrations SET attended=? WHERE id=?",attended,id);}}send(x,200,obj("ok",true));return;}
 throw new Fault(404,"Endpoint not found");
 }catch(Fault f){send(x,f.code,obj("error",f.getMessage()));}catch(SQLException e){System.err.println("Database operation failed ("+e.getSQLState()+")");send(x,500,obj("error","Database operation failed. Please retry."));}catch(IllegalArgumentException e){send(x,400,obj("error","Invalid request"));}catch(Exception e){System.err.println("Request failed: "+e.getClass().getSimpleName());send(x,500,obj("error","Unexpected server error"));}finally{x.close();}}
 private static final String DUMMY=Security.password("invalid-account-timing-padding");
 private void rate(HttpExchange x){String key=x.getRemoteAddress().getAddress().getHostAddress();synchronized(attempts){Instant now=Instant.now();attempts.entrySet().removeIf(e->e.getValue().until.isBefore(now));if(attempts.size()>10000)throw new Fault(429,"Too many requests; try again later");Attempts a=attempts.computeIfAbsent(key,k->new Attempts());if(++a.count>30)throw new Fault(429,"Too many sign-in attempts. Try again in ten minutes.");}}
 private void startSession(HttpExchange x,long uid){sessions.entrySet().removeIf(e->e.getValue().expires.isBefore(Instant.now()));String old=cookie(x);if(old!=null)sessions.remove(old);String token=Security.token();sessions.put(token,new Session(uid,Security.token(),Instant.now().plusSeconds(28800)));x.getResponseHeaders().add("Set-Cookie","CLSESSION="+token+"; Path=/; HttpOnly; SameSite=Strict; Max-Age=28800"+(secure?"; Secure":""));}
 private Session session(HttpExchange x){String cookie=cookie(x);if(cookie==null)return null;Session s=sessions.get(cookie);if(s!=null&&s.expires.isBefore(Instant.now())){sessions.remove(cookie);return null;}return s;}
 private String cookie(HttpExchange x){String c=x.getRequestHeaders().getFirst("Cookie");if(c!=null)for(String part:c.split(";"))if(part.trim().startsWith("CLSESSION="))return part.trim().substring(10);return null;}
 private static Map<String,String> parse(String s){var m=new HashMap<String,String>();if(s!=null&&!s.isEmpty())for(String p:s.split("&")){String[] a=p.split("=",2);String k=URLDecoder.decode(a[0],StandardCharsets.UTF_8),v=URLDecoder.decode(a.length>1?a[1]:"",StandardCharsets.UTF_8);if(m.putIfAbsent(k,v)!=null)throw new Fault(400,"Duplicate request field");}return m;}
 private static String text(Map<String,String> f,String key,int min,int max){String v=f.getOrDefault(key,"").trim();if(v.length()<min||v.length()>max||v.chars().anyMatch(c->c<32&&c!='\n'&&c!='\t'))throw new Fault(400,"Invalid "+key+" ("+min+"–"+max+" characters)");return v;}
 private static long id(Map<String,String> f,String key){try{long id=Long.parseLong(f.getOrDefault(key,""));if(id<1||id>Integer.MAX_VALUE)throw new Exception();return id;}catch(Exception e){throw new Fault(400,"Invalid "+key);}}
 private static void email(String e){if(e.length()>160||!e.matches("[A-Za-z0-9.!#$%&'*+/=?^_`{|}~-]+@[A-Za-z0-9-]+(?:\\.[A-Za-z0-9-]+)+"))throw new Fault(400,"Enter a valid email address");}
 private static void password(String p){if(p.length()<10||p.length()>128)throw new Fault(400,"Password must contain 10–128 characters");}
 private static Map<String,Object> event(Connection c,long id)throws SQLException{var rows=query(c,"SELECT * FROM events WHERE id=?",id);if(rows.isEmpty())throw new Fault(404,"Event not found");return rows.get(0);}
 private void asset(HttpExchange x,String path)throws IOException{if(!x.getRequestMethod().equals("GET")){send(x,405,obj("error","Method not allowed"));return;}String file=switch(path){case "/","/index.html"->"index.html";case "/app.js"->"app.js";case "/style.css"->"style.css";case "/logo.png"->"logo.png";default->null;};if(file==null){send(x,404,obj("error","Not found"));return;}try(InputStream in=App.class.getResourceAsStream("/web/"+file)){if(in==null){send(x,404,obj("error","Asset not found"));return;}byte[] bytes=in.readAllBytes();x.getResponseHeaders().set("Content-Type",file.endsWith(".png")?"image/png":file.endsWith(".js")?"text/javascript; charset=utf-8":file.endsWith(".css")?"text/css; charset=utf-8":"text/html; charset=utf-8");x.sendResponseHeaders(200,bytes.length);x.getResponseBody().write(bytes);}}
 private static void send(HttpExchange x,int status,Object body)throws IOException{byte[] b=Json.encode(body).getBytes(StandardCharsets.UTF_8);x.getResponseHeaders().set("Content-Type","application/json; charset=utf-8");x.sendResponseHeaders(status,b.length);x.getResponseBody().write(b);}
}
